def generate_signals(df: pd.DataFrame) -> pd.Series:
    ma60 = df['close'].rolling(window=60).mean()
    ma120 = df['close'].rolling(window=120).mean()
    cross_up = (ma60 > ma120) & (ma60.shift(1) <= ma120.shift(1))

    signals = pd.Series(0, index=df.index)
    in_pos = False
    peak = None

    for idx in df.index:
        c = df.loc[idx, 'close']
        if in_pos:
            if peak is None:
                peak = c
            else:
                peak = max(peak, c)
            if c < peak * 0.75:
                signals.loc[idx] = 0
                in_pos = False
                peak = None
            else:
                signals.loc[idx] = 1
        else:
            val = cross_up.loc[idx]
            if pd.notna(val) and val:
                signals.loc[idx] = 1
                in_pos = True
                peak = c
            else:
                signals.loc[idx] = 0
    return signals

def generate_signals(df: pd.DataFrame) -> pd.Series:
    if not isinstance(df.index, pd.DatetimeIndex):
        df = df.set_index(pd.to_datetime(df['date']))

    ret_120 = df['close'] / df['close'].shift(120) - 1

    month_ends = df.index.to_period('M').to_timestamp(how='end')
    sig_monthly = ret_120.reindex(month_ends)
    sig_monthly = (sig_monthly > 0).astype(int)

    signals = sig_monthly.reindex(df.index).ffill()
    signals = signals.fillna(0)

    return signals.astype(int)
